import{_ as a,o as i,c as s,ag as d}from"./chunks/framework.C9sp7nFj.js";const g=JSON.parse('{"title":"WaitSimAI 等待虚拟模拟量输入","description":"","frontmatter":{},"headers":[],"relativePath":"3. 指令/4. IO 指令/WaitSimAI.md","filePath":"3. 指令/4. IO 指令/WaitSimAI.md","lastUpdated":1778862643000}'),e={name:"3. 指令/4. IO 指令/WaitSimAI.md"};function r(n,t,o,l,h,p){return i(),s("div",null,[...t[0]||(t[0]=[d('<h1 id="waitsimai-等待虚拟模拟量输入" tabindex="-1">WaitSimAI 等待虚拟模拟量输入 <a class="header-anchor" href="#waitsimai-等待虚拟模拟量输入" aria-label="Permalink to &quot;WaitSimAI 等待虚拟模拟量输入&quot;">​</a></h1><p>虚拟模拟量输入等待指令用于在设定的时长内，监控指定的**虚拟模拟量输入（SimAI）**端口值。当该虚拟端口的实时数值与目标值相等时，程序继续执行。这通常用于程序间的复杂数据交互或仿真工艺流程中的数值同步。</p><h2 id="指令格式" tabindex="-1">指令格式 <a class="header-anchor" href="#指令格式" aria-label="Permalink to &quot;指令格式&quot;">​</a></h2><p><code>WaitSimAI (SIMAIN, VALUE, T, INTERENABLE, RET, [Goto])</code></p><p><code>WaitSimAI(虚拟模拟量输入端口, 目标触发值, 超时时间, 打断使能, 结果变量, [跳转行号])</code></p><p><em>(备注：带 [] 参数为可选参数)</em></p><hr><h2 id="参数详细说明" tabindex="-1">参数详细说明 <a class="header-anchor" href="#参数详细说明" aria-label="Permalink to &quot;参数详细说明&quot;">​</a></h2><table tabindex="0"><thead><tr><th>参数</th><th>类型</th><th>说明</th><th>默认值/备注</th></tr></thead><tbody><tr><td>SIMAIN</td><td>SimAI</td><td>需要监控的目标虚拟模拟量输入端口</td><td>必填</td></tr><tr><td>VALUE</td><td>real 或 REAL 变量</td><td>期望等待的数值</td><td>必填</td></tr><tr><td>T</td><td>int 或 INT 变量</td><td>等待限时，单位 ms（0：强制等待直到信号满足）</td><td>必填</td></tr><tr><td>INTERENABLE</td><td>int</td><td>程序暂停恢复后的计时逻辑（0：累计计时，1：重置计时）</td><td>必填</td></tr><tr><td>RET</td><td>INT 变量</td><td>返回指令执行结束后的状态记录（0：成功，1：超时）</td><td>必填</td></tr><tr><td>[Goto]</td><td>label</td><td>超时后程序指针跳转到的指定标签名</td><td>可选</td></tr></tbody></table><hr><h2 id="应用示例" tabindex="-1">应用示例 <a class="header-anchor" href="#应用示例" aria-label="Permalink to &quot;应用示例&quot;">​</a></h2><p><strong>示例 1：</strong></p><div class="language-estun vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">estun</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">WaitSimAI</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> (SimAI1, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">5.0</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1000</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">0</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, INT1)</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p><strong>逻辑描述：</strong></p><p>程序开始监测虚拟模拟量输入变量 <strong>SimAI1</strong>。</p><ol><li>如果在 <strong>1000ms</strong> 内，<strong>SimAI1</strong> 的值变为 <strong>5.0</strong>，则变量 <strong>INT1</strong> 赋值为 <strong>0</strong>，程序继续执行下一条指令。</li><li>如果在等待过程中（例如在第 500ms 时）程序暂停并随后恢复，由于 <code>INTERENABLE</code> 为 <strong>0</strong>，计时器将从 500ms 处<strong>继续累加</strong>。</li><li>若满 1000ms 仍未检测到 5.0，则 <strong>INT1</strong> 被置为 <strong>1</strong>（表示超时），程序继续向下运行。</li></ol>',16)])])}const c=a(e,[["render",r]]);export{g as __pageData,c as default};
